// AUTO-GENERATED from "Commercial Property Purchase Service Agreement - V0.2.txt" (V0.2) by scripts/genSalesAgreementClauses.js.
// Verbatim clause text; do not hand-edit — re-run the generator to refresh.
module.exports = [
  ["PURPOSE", "<p style=\"margin:6px 0;\">This Agreement sets out the terms and conditions under which Seventh Sky will provide Commercial Property Purchase Services to assist the Buyer in identifying, evaluating, negotiating and acquiring a suitable commercial property.</p><p style=\"margin:6px 0;\">The Agreement establishes the rights and responsibilities of both Parties in relation to commercial property search, inspections, due diligence coordination, negotiations, purchase documentation, settlement coordination and other agreed purchase support services.</p><p style=\"margin:6px 0;\">The specific Services, pricing and engagement scope applicable to each transaction shall be confirmed in the approved Quotation, Work Order or Schedule B.</p>"],
  ["TERM", "<p style=\"margin:6px 0;\">This Agreement becomes effective on the date it is signed by both Parties and continues until:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services have been completed;</li><li style=\"margin:2px 0;\">the property purchase has been completed or discontinued;</li><li style=\"margin:2px 0;\">all outstanding obligations have been fulfilled; or</li><li style=\"margin:2px 0;\">this Agreement is terminated in accordance with its terms.</li></ul><p style=\"margin:6px 0;\">Where the Buyer engages Seventh Sky on an exclusive basis, the exclusive engagement period shall be specified in the approved Quotation or Work Order.</p>"],
  ["SERVICES", "<p style=\"margin:6px 0;\">Depending on the selected Service Package, Seventh Sky may provide one or more of the following Services.</p><p style=\"margin:6px 0;\">Only the Services selected in Schedule A or the approved Work Order form part of this Agreement.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Buyer Consultation</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Initial Consultation</li><li style=\"margin:2px 0;\">☐ Commercial Property Requirement Assessment</li><li style=\"margin:2px 0;\">☐ Budget Planning Guidance</li><li style=\"margin:2px 0;\">☐ Investment Strategy Discussion</li><li style=\"margin:2px 0;\">☐ Commercial Market Guidance</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Commercial Property Search</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Commercial Property Search</li><li style=\"margin:2px 0;\">☐ Property Shortlisting</li><li style=\"margin:2px 0;\">☐ Seller Communication</li><li style=\"margin:2px 0;\">☐ Property Inspection Coordination</li><li style=\"margin:2px 0;\">☐ Property Evaluation Assistance</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Due Diligence &amp; Purchase Coordination</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Due Diligence Coordination</li><li style=\"margin:2px 0;\">☐ Ownership Document Coordination</li><li style=\"margin:2px 0;\">☐ Document Verification Coordination</li><li style=\"margin:2px 0;\">☐ Negotiation Support</li><li style=\"margin:2px 0;\">☐ Purchase Agreement Coordination</li><li style=\"margin:2px 0;\">☐ Settlement Coordination</li><li style=\"margin:2px 0;\">☐ Registration Coordination</li><li style=\"margin:2px 0;\">☐ Property Handover Coordination</li></ul><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Additional Services</p><ul style=\"margin:4px 0 8px 6px;padding:0;list-style:none;\"><li style=\"margin:2px 0;\">☐ Bank Loan Coordination</li><li style=\"margin:2px 0;\">☐ Property Valuation Coordination</li><li style=\"margin:2px 0;\">☐ Engineering Inspection Coordination</li><li style=\"margin:2px 0;\">☐ Land Survey Coordination</li><li style=\"margin:2px 0;\">☐ Legal Documentation Coordination</li><li style=\"margin:2px 0;\">☐ Other: _______________________</li></ul><p style=\"margin:6px 0;\">Additional Services may be included by written agreement.</p>"],
  ["BUYER REQUIREMENTS", "<p style=\"margin:6px 0;\">The Buyer's requirements shall be recorded in Schedule B or the approved Work Order.</p><p style=\"margin:6px 0;\">The information may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Preferred Property Type;</li><li style=\"margin:2px 0;\">Preferred Location;</li><li style=\"margin:2px 0;\">Intended Business Use;</li><li style=\"margin:2px 0;\">Estimated Purchase Budget;</li><li style=\"margin:2px 0;\">Financing Method;</li><li style=\"margin:2px 0;\">Preferred Property Size;</li><li style=\"margin:2px 0;\">Expected Purchase Timeframe;</li><li style=\"margin:2px 0;\">Investment Objectives;</li><li style=\"margin:2px 0;\">Selected Services; and</li><li style=\"margin:2px 0;\">Special Requirements.</li></ul><p style=\"margin:6px 0;\">Where any inconsistency exists between this Agreement and the approved Work Order or Schedule B, the approved Work Order or Schedule B shall prevail for that transaction.</p>"],
  ["BUYER RESPONSIBILITIES", "<p style=\"margin:6px 0;\">The Buyer agrees to:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide accurate personal, business and financial information;</li><li style=\"margin:2px 0;\">provide all documents reasonably required for the purchase process;</li><li style=\"margin:2px 0;\">promptly review quotations, offers and purchase documentation;</li><li style=\"margin:2px 0;\">obtain financing where required;</li><li style=\"margin:2px 0;\">pay all agreed Service Fees and approved third-party costs;</li><li style=\"margin:2px 0;\">cooperate with Seventh Sky and relevant third parties throughout the purchase process;</li><li style=\"margin:2px 0;\">promptly notify Seventh Sky of any material changes affecting the purchase; and</li><li style=\"margin:2px 0;\">obtain independent legal, taxation, financial, engineering and valuation advice where appropriate.</li></ul><p style=\"margin:6px 0;\">The Buyer remains responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">all purchasing decisions;</li><li style=\"margin:2px 0;\">financing arrangements;</li><li style=\"margin:2px 0;\">legal and regulatory compliance;</li><li style=\"margin:2px 0;\">taxation obligations;</li><li style=\"margin:2px 0;\">due diligence outcomes;</li><li style=\"margin:2px 0;\">government charges, registration fees and stamp duty; and</li><li style=\"margin:2px 0;\">obligations arising under the final Purchase Agreement.</li></ul>"],
  ["RESPONSIBILITIES OF SEVENTH SKY", "<p style=\"margin:6px 0;\">Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">provide the agreed Services with reasonable care, skill and professional diligence;</li><li style=\"margin:2px 0;\">assist the Buyer in identifying suitable commercial properties;</li><li style=\"margin:2px 0;\">coordinate communication with sellers and their authorised representatives;</li><li style=\"margin:2px 0;\">coordinate property inspections and meetings;</li><li style=\"margin:2px 0;\">coordinate due diligence and document review where included within the agreed Services;</li><li style=\"margin:2px 0;\">coordinate negotiations, purchase documentation and settlement activities where requested;</li><li style=\"margin:2px 0;\">coordinate communication with approved third-party professionals where authorised;</li><li style=\"margin:2px 0;\">maintain appropriate records relating to the Services; and</li><li style=\"margin:2px 0;\">keep the Buyer reasonably informed throughout the engagement.</li></ul><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts solely as a Commercial Property Purchase Service Provider and Coordinator and does not become the property owner, seller, developer, financier, legal adviser, accountant, engineer, surveyor or government authority.</p><p style=\"margin:6px 0;\">Seventh Sky shall not make binding purchasing decisions, execute contracts or commit the Buyer to any financial obligation unless expressly authorised in writing by the Buyer.</p>"],
  ["QUOTATIONS & WORK ORDERS", "<p style=\"margin:6px 0;\">Before commencing the Services, Seventh Sky may issue a Quotation or Work Order specifying:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">the agreed Services;</li><li style=\"margin:2px 0;\">selected Service Package;</li><li style=\"margin:2px 0;\">engagement type (exclusive or non-exclusive);</li><li style=\"margin:2px 0;\">Professional Service Fees;</li><li style=\"margin:2px 0;\">success fee or commission (where applicable);</li><li style=\"margin:2px 0;\">approved third-party costs;</li><li style=\"margin:2px 0;\">payment schedule;</li><li style=\"margin:2px 0;\">expected project timeframe; and</li><li style=\"margin:2px 0;\">any special conditions.</li></ul><p style=\"margin:6px 0;\">Additional Services requested after commencement may require a revised Quotation, Work Order or approved variation before work proceeds.</p>"],
  ["SERVICE FEES & PAYMENT", "<p style=\"margin:6px 0;\">The Professional Service Fees payable under this Agreement shall be specified in the approved Quotation, Work Order or Schedule B.</p><p style=\"margin:6px 0;\">Depending on the selected Service Package, the Service Fees may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Buyer Consultation;</li><li style=\"margin:2px 0;\">Commercial Property Search;</li><li style=\"margin:2px 0;\">Property Inspection Coordination;</li><li style=\"margin:2px 0;\">Due Diligence Coordination;</li><li style=\"margin:2px 0;\">Negotiation Support;</li><li style=\"margin:2px 0;\">Purchase Documentation Coordination;</li><li style=\"margin:2px 0;\">Settlement Coordination;</li><li style=\"margin:2px 0;\">Success Fee or Commission (where applicable);</li><li style=\"margin:2px 0;\">Approved Third-Party Costs; and</li><li style=\"margin:2px 0;\">Additional Services requested by the Buyer.</li></ul><p style=\"margin:6px 0;\">The Buyer agrees to pay all agreed Professional Service Fees in accordance with the approved payment schedule.</p><p style=\"margin:6px 0;\">Government charges, stamp duty, registration fees, taxes, legal costs, valuation fees, survey fees, engineering inspection costs, loan processing fees and other approved third-party expenses remain the responsibility of the Buyer unless otherwise agreed in writing.</p>"],
  ["PAYMENT TERMS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Professional Service Fees</p><p style=\"margin:6px 0;\">Professional Service Fees shall be payable in accordance with the approved Quotation, Work Order or Schedule B.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">Success Fee Engagement</p><p style=\"margin:6px 0;\">Where the Parties agree to a success fee arrangement, the agreed success fee or commission becomes payable upon successful completion of the property purchase or as otherwise specified in the approved Quotation or Work Order.</p><p style=\"margin:6px 0;\">Invoices are payable within the period stated on the invoice.</p><p style=\"margin:6px 0;\">Late payment may result in suspension of the Services until outstanding amounts have been paid.</p>"],
  ["COMMERCIAL PROPERTY PURCHASE SERVICES", "<p style=\"margin:6px 0;\">Seventh Sky will use reasonable efforts to assist the Buyer in identifying and purchasing a suitable commercial property in accordance with the agreed scope of Services.</p><p style=\"margin:6px 0;\">Depending on the selected Service Package, the Services may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commercial property search;</li><li style=\"margin:2px 0;\">seller communication;</li><li style=\"margin:2px 0;\">property inspection coordination;</li><li style=\"margin:2px 0;\">due diligence coordination;</li><li style=\"margin:2px 0;\">ownership document coordination;</li><li style=\"margin:2px 0;\">negotiation support;</li><li style=\"margin:2px 0;\">purchase documentation coordination;</li><li style=\"margin:2px 0;\">settlement coordination;</li><li style=\"margin:2px 0;\">property handover coordination; and</li><li style=\"margin:2px 0;\">other agreed purchase support services.</li></ul><p style=\"margin:6px 0;\">The Buyer acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">suitable commercial properties are subject to market availability;</li><li style=\"margin:2px 0;\">asking prices, market values and purchasing conditions may change at any time;</li><li style=\"margin:2px 0;\">sellers retain the right to accept, reject or withdraw offers;</li><li style=\"margin:2px 0;\">financing approval and due diligence outcomes may affect the transaction; and</li><li style=\"margin:2px 0;\">Seventh Sky does not guarantee the successful purchase of any property.</li></ul>"],
  ["PROJECT TIMELINES", "<p style=\"margin:6px 0;\">Estimated commencement and completion dates will be provided in the approved Quotation, Work Order or Schedule B where applicable.</p><p style=\"margin:6px 0;\">Project timeframes may vary depending on factors including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property availability;</li><li style=\"margin:2px 0;\">market conditions;</li><li style=\"margin:2px 0;\">seller response times;</li><li style=\"margin:2px 0;\">finance approval;</li><li style=\"margin:2px 0;\">legal documentation;</li><li style=\"margin:2px 0;\">valuation or survey requirements;</li><li style=\"margin:2px 0;\">settlement arrangements;</li><li style=\"margin:2px 0;\">government approvals;</li><li style=\"margin:2px 0;\">public holidays; and</li><li style=\"margin:2px 0;\">other circumstances beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where delays occur, Seventh Sky will keep the Buyer reasonably informed and provide revised estimated timeframes where reasonably practicable.</p>"],
  ["VARIATIONS & ADDITIONAL SERVICES", "<p style=\"margin:6px 0;\">The Buyer may request changes to the agreed scope of Services at any time.</p><p style=\"margin:6px 0;\">Additional Services may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">additional property searches;</li><li style=\"margin:2px 0;\">additional inspections;</li><li style=\"margin:2px 0;\">extended negotiations;</li><li style=\"margin:2px 0;\">additional due diligence coordination;</li><li style=\"margin:2px 0;\">loan assistance coordination;</li><li style=\"margin:2px 0;\">valuation or survey coordination;</li><li style=\"margin:2px 0;\">legal documentation coordination; or</li><li style=\"margin:2px 0;\">any other Services requested by the Buyer.</li></ul><p style=\"margin:6px 0;\">Where a variation affects the Professional Service Fees, project scope or timeframe, Seventh Sky will provide a revised Quotation, Work Order or variation for approval before proceeding.</p><p style=\"margin:6px 0;\">Immediate action reasonably required to protect the Buyer's interests or facilitate the purchase process may be undertaken without prior approval where obtaining approval is not reasonably practicable.</p>"],
  ["THIRD-PARTY SERVICES", "<p style=\"margin:6px 0;\">Where required, Seventh Sky may coordinate independent third-party professionals to support the delivery of the agreed Services.</p><p style=\"margin:6px 0;\">These may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">property sellers or developers;</li><li style=\"margin:2px 0;\">lawyers and conveyancers;</li><li style=\"margin:2px 0;\">banks and financial institutions;</li><li style=\"margin:2px 0;\">valuers;</li><li style=\"margin:2px 0;\">surveyors;</li><li style=\"margin:2px 0;\">engineers;</li><li style=\"margin:2px 0;\">government authorities; and</li><li style=\"margin:2px 0;\">other approved professional service providers.</li></ul><p style=\"margin:6px 0;\">The Buyer acknowledges that these providers operate independently and remain responsible for their own advice, reports and professional services.</p><p style=\"margin:6px 0;\">Unless otherwise agreed in writing, Seventh Sky acts solely as the coordinator of these Services and is not responsible for the advice, reports, products or services provided by independent third parties.</p>"],
  ["SERVICE COMPLETION", "<p style=\"margin:6px 0;\">The Services shall be deemed complete when Seventh Sky has substantially delivered the Services specified in the approved Quotation, Work Order or Schedule B.</p><p style=\"margin:6px 0;\">Depending on the agreed scope, completion may include:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commercial property search completed;</li><li style=\"margin:2px 0;\">suitable properties identified;</li><li style=\"margin:2px 0;\">property inspections coordinated;</li><li style=\"margin:2px 0;\">due diligence coordination completed;</li><li style=\"margin:2px 0;\">negotiations completed;</li><li style=\"margin:2px 0;\">purchase documentation coordinated;</li><li style=\"margin:2px 0;\">settlement coordination completed;</li><li style=\"margin:2px 0;\">property handover coordinated; or</li><li style=\"margin:2px 0;\">other agreed Services completed.</li></ul><p style=\"margin:6px 0;\">Where Seventh Sky is engaged for ongoing post-purchase support, the Services shall continue until the agreed engagement period expires or is terminated in accordance with this Agreement.</p>"],
  ["CLIENT COMPLAINTS", "<p style=\"margin:6px 0;\">If the Buyer is dissatisfied with any aspect of the Services, the Buyer should notify Seventh Sky as soon as reasonably practicable.</p><p style=\"margin:6px 0;\">Upon receiving a complaint, Seventh Sky will:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">acknowledge receipt of the complaint;</li><li style=\"margin:2px 0;\">investigate the matter;</li><li style=\"margin:2px 0;\">communicate with the Buyer throughout the review process;</li><li style=\"margin:2px 0;\">take reasonable steps to resolve the issue where appropriate; and</li><li style=\"margin:2px 0;\">advise the Buyer of the outcome.</li></ul><p style=\"margin:6px 0;\">Where a complaint relates to a Seller or an independent third-party service provider, Seventh Sky will assist in facilitating communication where reasonably practicable but is not responsible for that third party's acts, omissions or performance.</p><p style=\"margin:6px 0;\">Nothing in this Agreement limits any rights available under applicable law.</p>"],
  ["LIABILITY", "<p style=\"margin:6px 0;\">Seventh Sky will perform the agreed Services with reasonable care, skill and professional diligence.</p><p style=\"margin:6px 0;\">The Buyer acknowledges that Seventh Sky acts solely as a Commercial Property Purchase Service Provider and Coordinator and does not provide legal, financial, taxation, accounting, valuation, engineering, surveying or investment advice.</p><p style=\"margin:6px 0;\">The Buyer remains responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">making all purchasing decisions;</li><li style=\"margin:2px 0;\">obtaining finance approval;</li><li style=\"margin:2px 0;\">completing appropriate due diligence;</li><li style=\"margin:2px 0;\">reviewing legal documentation;</li><li style=\"margin:2px 0;\">obtaining independent professional advice where appropriate; and</li><li style=\"margin:2px 0;\">complying with all legal obligations relating to the property purchase.</li></ul><p style=\"margin:6px 0;\">Seventh Sky is not responsible for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">decisions made by the Buyer or Seller;</li><li style=\"margin:2px 0;\">acceptance or rejection of purchase offers;</li><li style=\"margin:2px 0;\">changes in market values or purchase prices;</li><li style=\"margin:2px 0;\">inaccurate information supplied by Sellers or third parties;</li><li style=\"margin:2px 0;\">the acts or omissions of independent contractors or professional advisers; or</li><li style=\"margin:2px 0;\">professional advice provided by independent third-party professionals.</li></ul>"],
  ["LIMITATION OF LIABILITY", "<p style=\"margin:6px 0;\">To the maximum extent permitted by law, Seventh Sky shall not be liable for:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">failure to secure a particular commercial property;</li><li style=\"margin:2px 0;\">withdrawal of a property from the market;</li><li style=\"margin:2px 0;\">changes in purchase price or commercial terms;</li><li style=\"margin:2px 0;\">delays in negotiations, finance approval, settlement or registration;</li><li style=\"margin:2px 0;\">hidden defects, encumbrances or matters not reasonably identifiable through the agreed Services;</li><li style=\"margin:2px 0;\">inaccurate information supplied by Sellers or third parties;</li><li style=\"margin:2px 0;\">loss of profit, loss of business opportunity, investment loss or other indirect or consequential loss; or</li><li style=\"margin:2px 0;\">events beyond Seventh Sky's reasonable control.</li></ul><p style=\"margin:6px 0;\">Where liability cannot legally be excluded, Seventh Sky's total liability shall not exceed the Professional Service Fees paid by the Buyer for the Services giving rise to the claim.</p><p style=\"margin:6px 0;\">Nothing in this clause excludes liability that cannot legally be excluded under applicable law.</p>"],
  ["CONFIDENTIALITY & PRIVACY", "<p style=\"margin:6px 0;\">Both Parties agree to keep confidential all non-public information obtained through this Agreement.</p><p style=\"margin:6px 0;\">Seventh Sky may collect, use and disclose information only for the purpose of:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">providing the agreed Services;</li><li style=\"margin:2px 0;\">identifying and evaluating suitable commercial properties;</li><li style=\"margin:2px 0;\">communicating with Sellers and authorised third parties;</li><li style=\"margin:2px 0;\">coordinating inspections, due diligence and settlement activities;</li><li style=\"margin:2px 0;\">preparing quotations, reports, invoices and management records;</li><li style=\"margin:2px 0;\">complying with legal obligations; and</li><li style=\"margin:2px 0;\">managing its business operations.</li></ul><p style=\"margin:6px 0;\">Neither Party shall disclose confidential information to any third party without prior consent unless required by law.</p><p style=\"margin:6px 0;\">These obligations continue after completion or termination of this Agreement.</p>"],
  ["FORCE MAJEURE", "<p style=\"margin:6px 0;\">Neither Party shall be liable for delays or failure to perform its obligations where caused by events beyond its reasonable control, including:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">natural disasters;</li><li style=\"margin:2px 0;\">floods;</li><li style=\"margin:2px 0;\">fire;</li><li style=\"margin:2px 0;\">pandemics;</li><li style=\"margin:2px 0;\">government restrictions;</li><li style=\"margin:2px 0;\">industrial action;</li><li style=\"margin:2px 0;\">utility failures;</li><li style=\"margin:2px 0;\">civil unrest; or</li><li style=\"margin:2px 0;\">other unforeseen events.</li></ul><p style=\"margin:6px 0;\">The affected Party shall notify the other Party as soon as reasonably practicable and resume performance once the event has ended.</p>"],
  ["BUYER ACKNOWLEDGEMENTS", "<p style=\"margin:6px 0;\">The Buyer acknowledges that:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">they have read and understood this Agreement;</li><li style=\"margin:2px 0;\">all information provided to Seventh Sky is true, accurate and complete to the best of their knowledge;</li><li style=\"margin:2px 0;\">Seventh Sky provides Commercial Property Purchase Services only and is not the Seller, developer or property owner;</li><li style=\"margin:2px 0;\">suitable commercial properties are subject to market availability and negotiation;</li><li style=\"margin:2px 0;\">Sellers retain the final decision regarding acceptance of purchase offers;</li><li style=\"margin:2px 0;\">market values, purchase prices and commercial terms may change before a contract is executed;</li><li style=\"margin:2px 0;\">independent legal, taxation, accounting, engineering, valuation and financial advice should be obtained where appropriate;</li><li style=\"margin:2px 0;\">independent third-party professionals remain responsible for their own advice and services;</li><li style=\"margin:2px 0;\">all agreed Professional Service Fees, approved expenses and third-party costs remain payable in accordance with this Agreement; and</li><li style=\"margin:2px 0;\">they have had the opportunity to obtain independent legal advice before entering into this Agreement.</li></ul>"],
  ["SUSPENSION & TERMINATION", "<p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.1 Suspension</p><p style=\"margin:6px 0;\">Seventh Sky may suspend all or part of the Services where the Buyer:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">fails to pay any outstanding amount in accordance with this Agreement;</li><li style=\"margin:2px 0;\">provides false, misleading or incomplete information;</li><li style=\"margin:2px 0;\">fails to provide information or instructions reasonably required to perform the Services;</li><li style=\"margin:2px 0;\">requests Seventh Sky to undertake any unlawful activity; or</li><li style=\"margin:2px 0;\">commits a material breach of this Agreement.</li></ul><p style=\"margin:6px 0;\">Where reasonably practicable, Seventh Sky will notify the Buyer before suspending the Services.</p><p style=\"margin:10px 0 4px;font-weight:700;color:#012a4e;\">21.2 Termination</p><p style=\"margin:6px 0;\">Either Party may terminate this Agreement by providing written notice to the other Party.</p><p style=\"margin:6px 0;\">Seventh Sky may terminate this Agreement immediately where the Buyer:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">commits a material breach of this Agreement;</li><li style=\"margin:2px 0;\">repeatedly fails to pay agreed Professional Service Fees;</li><li style=\"margin:2px 0;\">engages in fraudulent or unlawful conduct;</li><li style=\"margin:2px 0;\">intentionally circumvents Seventh Sky in breach of this Agreement; or</li><li style=\"margin:2px 0;\">otherwise acts in a manner that makes continuation of the Services unreasonable.</li></ul><p style=\"margin:6px 0;\">Upon termination:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">Professional Service Fees for Services already completed remain payable;</li><li style=\"margin:2px 0;\">approved third-party costs remain payable;</li><li style=\"margin:2px 0;\">obligations intended to survive termination shall continue; and</li><li style=\"margin:2px 0;\">termination does not affect any rights or obligations accrued before the termination date.</li></ul>"],
  ["NON-CIRCUMVENTION", "<p style=\"margin:6px 0;\">The Buyer acknowledges that Seventh Sky invests considerable time, expertise and commercial resources in identifying suitable commercial properties, coordinating inspections, facilitating negotiations and introducing purchase opportunities.</p><p style=\"margin:6px 0;\">Accordingly, where Seventh Sky introduces a property, Seller, developer or authorised representative, the Buyer agrees not to intentionally bypass Seventh Sky to avoid payment of the agreed Professional Service Fees or success fee.</p><p style=\"margin:6px 0;\">This obligation applies during the term of this Agreement and for twelve (12) months following the relevant introduction.</p><p style=\"margin:6px 0;\">This clause does not prevent the Buyer from purchasing a property that was not introduced by Seventh Sky.</p>"],
  ["GENERAL PROVISIONS", "<p style=\"margin:6px 0;\">Unless otherwise agreed in writing:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">this Agreement, together with the accepted Quotation, Work Order and Schedules, constitutes the entire agreement between the Parties;</li><li style=\"margin:2px 0;\">any amendment to this Agreement must be made in writing and accepted by both Parties;</li><li style=\"margin:2px 0;\">failure by either Party to enforce any provision shall not constitute a waiver of that provision;</li><li style=\"margin:2px 0;\">if any provision is found to be invalid or unenforceable, the remaining provisions shall remain in full force and effect; and</li><li style=\"margin:2px 0;\">notices under this Agreement may be delivered by hand, registered post, courier or email.</li></ul>"],
  ["GOVERNING LAW", "<p style=\"margin:6px 0;\">This Agreement shall be governed by the laws of the People's Republic of Bangladesh.</p><p style=\"margin:6px 0;\">The Parties agree to use reasonable efforts to resolve any dispute through good faith discussions before commencing legal proceedings.</p><p style=\"margin:6px 0;\">Where a dispute cannot be resolved through negotiation, either Party may refer the matter to the competent courts of Bangladesh.</p>"],
  ["EXECUTION", "<p style=\"margin:6px 0;\">By signing this Agreement, the Parties confirm that they:</p><ul style=\"margin:4px 0 8px 18px;padding:0;list-style-type:disc;\"><li style=\"margin:2px 0;\">have read and understood this Agreement;</li><li style=\"margin:2px 0;\">have had the opportunity to obtain independent legal advice;</li><li style=\"margin:2px 0;\">agree to be bound by the terms of this Agreement; and</li><li style=\"margin:2px 0;\">enter into this Agreement voluntarily.</li></ul><p style=\"margin:6px 0;\">This Agreement may be executed in counterparts and by electronic signature, each of which shall be deemed an original.</p>"],
];
